SELECT id FROM job_log


        AND job_group = #{jobGroup}


        AND job_id = #{jobId}


        AND trigger_time  <=  #{clearBeforeTime}


        AND id NOT in(
        SELECT id FROM(
        SELECT id FROM job_log AS t


                AND t.job_group = #{jobGroup}


                AND t.job_id = #{jobId}


        ORDER BY t.trigger_time desc
        LIMIT 0, #{clearBeforeNum}
        ) t1
        )


order by id asc
LIMIT #{pagesize}

SELECT job_id AS jobId, COUNT(*) AS failCount
FROM job_log
WHERE is_deleted = 0
  AND (handle_code IS NULL OR (handle_code != 0 AND handle_code != 200))
AND trigger_time >= #{start}
AND trigger_time <= #{end}
AND job_id = #{jobId}
GROUP BY job_id
ORDER BY failCount DESC
LIMIT #{limit}

SELECT id FROM job_log
WHERE is_deleted = 0
  AND (handle_code IS NULL OR (handle_code != 0 AND handle_code != 200))
AND trigger_time >= #{start}
AND trigger_time <= #{end}
AND job_id = #{jobId}
ORDER BY id DESC
LIMIT #{limit}
